using BelediyeEnvanter.Data;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Microsoft.AspNetCore.Authorization;
namespace BelediyeEnvanter.Controllers;
[Authorize] public class DepartmentsController(AppDbContext db):Controller{
public async Task<IActionResult> Index()=>View(await db.Departments.Include(x=>x.Directorates).OrderBy(x=>x.Name).ToListAsync());
async Task Log(string islem,string aciklama){db.AuditLogs.Add(new(){Kullanici=User.Identity?.Name??"Bilinmiyor",Islem=islem,Aciklama=aciklama});await db.SaveChangesAsync();}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>AddDepartment(string name){if(!string.IsNullOrWhiteSpace(name)&&!await db.Departments.AnyAsync(x=>x.Name==name.Trim())){db.Departments.Add(new(){Name=name.Trim()});await db.SaveChangesAsync();await Log("Daire Başkanlığı Ekleme",$"{name} eklendi.");}return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>AddDirectorate(string name,int departmentId){if(!string.IsNullOrWhiteSpace(name)&&departmentId>0&&!await db.Directorates.AnyAsync(x=>x.Name==name.Trim()&&x.DepartmentId==departmentId)){db.Directorates.Add(new(){Name=name.Trim(),DepartmentId=departmentId});await db.SaveChangesAsync();await Log("Müdürlük Ekleme",$"{name} eklendi.");}return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>UpdateDepartment(int id,string name){var d=await db.Departments.FindAsync(id);if(d!=null&&!string.IsNullOrWhiteSpace(name)){var eski=d.Name;d.Name=name.Trim();await db.SaveChangesAsync();await Log("Daire Başkanlığı Düzenleme",$"{eski} → {d.Name}");}return RedirectToAction(nameof(Index));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>UpdateDirectorate(int id,string name,int departmentId){var m=await db.Directorates.FindAsync(id);if(m!=null&&!string.IsNullOrWhiteSpace(name)){var eski=m.Name;m.Name=name.Trim();m.DepartmentId=departmentId;await db.SaveChangesAsync();await Log("Müdürlük Düzenleme",$"{eski} → {m.Name}");}return RedirectToAction(nameof(Index));}
public async Task<IActionResult>DeleteDepartment(int id){var d=await db.Departments.Include(x=>x.Directorates).FirstOrDefaultAsync(x=>x.Id==id);if(d!=null&&!d.Directorates.Any()){var ad=d.Name;db.Remove(d);await db.SaveChangesAsync();await Log("Daire Başkanlığı Silme",$"{ad} silindi.");}return RedirectToAction(nameof(Index));}
public async Task<IActionResult>DeleteDirectorate(int id){var m=await db.Directorates.Include(x=>x.Rooms).FirstOrDefaultAsync(x=>x.Id==id);if(m!=null&&!m.Rooms.Any()){var ad=m.Name;db.Remove(m);await db.SaveChangesAsync();await Log("Müdürlük Silme",$"{ad} silindi.");}return RedirectToAction(nameof(Index));}}
